/**
 * Post codes (Beitragscode, decision D5 of PORTAL-ORGANISCH-BAUPLAN.md):
 * generated by the portal (apps/portal/src/lib/post-code.ts), 5 characters,
 * consonants without vowels plus digits 2-9, at least one of each. Opaque by
 * construction: a code can never spell a word or a treatment.
 *
 * Decision D6: `utm_content` stays in the page address ONLY when it matches
 * this pattern, so a reload keeps the post. The inline attribution script
 * (components/tracking/attribution-script.tsx) carries the same regex as a
 * literal; lib/post-code.test.ts pins both to POST_CODE_PATTERN_SOURCE, and
 * the portal's test pins its copy to the same string.
 */

export const POST_CODE_PATTERN_SOURCE =
  "^(?=[bcdfghjkmnpqrstvwxz2-9]*[2-9])(?=[bcdfghjkmnpqrstvwxz2-9]*[bcdfghjkmnpqrstvwxz])[bcdfghjkmnpqrstvwxz2-9]{5}$";
const POST_CODE_PATTERN = new RegExp(POST_CODE_PATTERN_SOURCE);

/** True only for a well-formed post code. Anything else is never treated as one. */
export function isPostCode(value: unknown): value is string {
  return typeof value === "string" && POST_CODE_PATTERN.test(value);
}
